const UPDATE_URL = "https://github.com/IvanPJH05/meaningful-plushies-fulfilment/releases/latest/download/app-debug.apk";
const UPDATE_API = "https://api.github.com/repos/IvanPJH05/meaningful-plushies-fulfilment/releases/latest";
const money = new Intl.NumberFormat("en-MY", { style: "currency", currency: "MYR", maximumFractionDigits: 2 });

type Session = { token: string; username: string; displayName: string; role: "admin" | "staff" };
type OfflineMedia = { voice?: boolean; photo?: boolean; attachment?: boolean; shippingLabel?: boolean };
type Order = { id: string; orderNumber: string; orderDate: string; customerName: string; phone: string; address: string; plushName: string; status: string; character: string; product: string; voiceLength: number; paymentProcessor: string; totalAmount: number; courier: string; trackingNumber: string; updatedAt?: string; offlineMedia?: OfflineMedia };
type OrderDetails = { email: string; subtotalAmount: number; shippingAmount: number; discountAmount: number; outstandingBalance: number; meaningfulNote: string; plushGender?: string; plushBirthDate?: string; plushBelongsTo?: string; voice: { url: string; fileName: string } | null };
type Detail = { order: Order; details: OrderDetails };
type Dashboard = { counts: Record<string, number>; orders: Order[]; totalCount: number; hasMore: boolean; latestUpdatedAt: string | null; savedAt: number };
type ManualOrder = { id: string; reference?: string; customerName: string; customerEmail: string; phoneOriginal: string; character: string; productDisplayName: string; customisationSessionId: string; speakerSeconds?: number; amountToCollect?: number | null; shippingRegion?: "WEST" | "EAST"; shippingAddress: { address1: string; address2?: string; city: string; province: string; zip: string }; paymentReceipts: Array<{ fileName: string; url: string }>; isCod: boolean; status: "awaiting_payment" | "ready_to_create" | "created" | "cancelled"; shopifyOrderName: string; createdAt: string; updatedAt?: string; paymentApprovedAt: string };
type ManualDetail = { intake: ManualOrder; form: { plushName?: string; gender?: string; birthDate?: string; belongsTo?: string; meaningfulNote?: string } | null; voiceUrl: string; voiceFileName: string };
type Workspace = "fulfilment" | "manual_orders" | "reports" | "updates";
type SourceFilter = "all" | "shopify" | "tiktok";
type SalesReport = { sales: { gross: number; totalCollected: number; productDiscounted: number; shippingDiscounted: number; totalFees: number; collected: number }; channel: { shopify: { count: number; sales: number }; tiktok: { count: number; sales: number } }; orderCount: number; savedAt?: number };
type UpdateRelease = { version: string; releasedAt: string; downloadUrl: string; fileName: string };
type OfflineArchive = { version: 2 | 3; dashboard: Dashboard; orderDetails: Record<string, Detail>; manualOrders: ManualOrder[]; manualHistory: ManualOrder[]; manualDetails: Record<string, ManualDetail>; salesReport: SalesReport | null; savedAt: number };
type AutoSyncFrequency = "open" | "hourly" | "daily" | "manual";
const InAppUpdate = registerPlugin<{ install(options: { path: string }): Promise<void>; downloadAndInstall(options: { url: string; fileName: string }): Promise<void> }>("InAppUpdate");

const labels: Record<string, string> = { awaiting_customisation: "Awaiting customisation", new_order: "New order", uploading_audio: "Uploading audio", sent_for_sewing: "Sent for sewing", packed: "Packed", shipped: "Shipped", issue: "Issue" };
const next: Record<string, string> = { awaiting_customisation: "new_order", new_order: "uploading_audio", uploading_audio: "sent_for_sewing", sent_for_sewing: "packed", packed: "shipped" };
function stored<T>(key: string, fallback: T): T { try { const value = localStorage.getItem(key); return value ? JSON.parse(value) as T : fallback; } catch { return fallback; } }
function save(key: string, value: unknown) { try { localStorage.setItem(key, JSON.stringify(value)); } catch { /* cache is optional */ } }
function hasStored(key: string) { try { return localStorage.getItem(key) !== null; } catch { return false; } }
function date(value: string) { return value ? new Date(value).toLocaleDateString("en-MY", { day: "numeric", month: "short", year: "numeric" }) : "—"; }
function exactTime(value: string) { return value ? new Intl.DateTimeFormat("en-MY", { dateStyle: "medium", timeStyle: "medium", timeZone: "Asia/Kuala_Lumpur" }).format(new Date(value)) : "Checking release time…"; }
function manualStatus(order: ManualOrder) { if (order.status === "created") return order.isCod ? "COD" : "Paid"; if (order.status === "ready_to_create") return order.isCod ? "COD approved" : "Receipt attached"; return "Awaiting payment"; }
function manualAddress(order: ManualOrder) { const a = order.shippingAddress; return [a.address1, a.address2, a.city, a.province, a.zip].filter(Boolean).join(", "); }

function App() {
  const [session, setSession] = useState<Session | null>(() => stored<Session | null>(SESSION_KEY, null));
  const [username, setUsername] = useState(""); const [password, setPassword] = useState("");
  const [dashboard, setDashboard] = useState<Dashboard>(() => stored<Dashboard>(DASHBOARD_KEY, { counts: {}, orders: [], totalCount: 0, hasMore: false, latestUpdatedAt: null, savedAt: 0 }));
  const [selected, setSelected] = useState<Detail | null>(null); const [manualDetail, setManualDetail] = useState<ManualDetail | null>(null);
  const [orderDetailsCache, setOrderDetailsCache] = useState<Record<string, Detail>>(() => stored<Record<string, Detail>>(ORDER_DETAILS_KEY, {}));
  const [workspace, setWorkspace] = useState<Workspace>("fulfilment"); const [workspaceOpen, setWorkspaceOpen] = useState(false);
  const [manualOrders, setManualOrders] = useState<ManualOrder[]>(() => stored<ManualOrder[]>(MANUAL_APPROVALS_KEY, [])); const [manualHistory, setManualHistory] = useState<ManualOrder[]>(() => stored<ManualOrder[]>(MANUAL_HISTORY_KEY, [])); const [manualPage, setManualPage] = useState<"approvals" | "history">("approvals");
  const [manualDetailsCache, setManualDetailsCache] = useState<Record<string, ManualDetail>>(() => stored<Record<string, ManualDetail>>(MANUAL_DETAILS_KEY, {}));
  const [manualCacheReady, setManualCacheReady] = useState(() => hasStored(MANUAL_APPROVALS_KEY) && hasStored(MANUAL_HISTORY_KEY));
  const [statusFilter, setStatusFilter] = useState("all"); const [sourceFilter, setSourceFilter] = useState<SourceFilter>("all"); const [fromDate, setFromDate] = useState(""); const [toDate, setToDate] = useState(""); const [salesReport, setSalesReport] = useState<SalesReport | null>(() => stored<SalesReport | null>(REPORT_KEY, null)); const [reportLoading, setReportLoading] = useState(false);
  const [updateRelease, setUpdateRelease] = useState<UpdateRelease | null>(null);
  const [autoSyncFrequency, setAutoSyncFrequency] = useState<AutoSyncFrequency>(() => stored<AutoSyncFrequency>(AUTO_SYNC_KEY, "daily")); const [updateDownloading, setUpdateDownloading] = useState(false);
  const [notice, setNotice] = useState(""); const [busy, setBusy] = useState(false); const [loadingMore, setLoadingMore] = useState(false); const [opening, setOpening] = useState(false); const [offlineSync, setOfflineSync] = useState<{ active: boolean; completed: number; total: number; media: number }>({ active: false, completed: 0, total: 0, media: 0 });
  const [updatesAvailable, setUpdatesAvailable] = useState(false); const [pullDistance, setPullDistance] = useState(0);
  const archiveLoaded = useRef(Capacitor.getPlatform() === "web");
  const initialWorkspaceLoad = useRef(true);
  const [archiveReady, setArchiveReady] = useState(Capacitor.getPlatform() === "web");

  function orderFilters() { const params = new URLSearchParams({ pageSize: String(PAGE_SIZE), status: statusFilter, source: sourceFilter }); if (fromDate) params.set("from", fromDate); if (toDate) params.set("to", toDate); return params; }
  async function saveOfflineArchive(archive: OfflineArchive) { if (Capacitor.getPlatform() === "web") return; try { await Filesystem.writeFile({ path: OFFLINE_ARCHIVE_PATH, data: JSON.stringify(archive), directory: Directory.Data, encoding: Encoding.UTF8, recursive: true }); } catch { /* The normal app cache remains available if device storage is temporarily unavailable. */ } }
  async function loadOfflineArchive() { if (Capacitor.getPlatform() === "web") return; try { let saved; try { saved = await Filesystem.readFile({ path: OFFLINE_ARCHIVE_PATH, directory: Directory.Data, encoding: Encoding.UTF8 }); } catch { saved = await Filesystem.readFile({ path: "meaningful-fulfilment/archive-v2.json", directory: Directory.Data, encoding: Encoding.UTF8 }); } const archive = JSON.parse(String(saved.data)) as OfflineArchive; if ((archive.version === 2 || archive.version === 3) && Array.isArray(archive.dashboard?.orders)) { setDashboard(archive.dashboard); setOrderDetailsCache(archive.orderDetails || {}); setManualOrders(archive.manualOrders || []); setManualHistory(archive.manualHistory || []); setManualDetailsCache(archive.manualDetails || {}); setManualCacheReady(true); setSalesReport(archive.salesReport || null); } } catch { /* First install or an older cache: the background archive will replace it. */ } finally { archiveLoaded.current = true; setArchiveReady(true); } }
  async function base64(blob: Blob) { return await new Promise<string>((resolve, reject) => { const reader = new FileReader(); reader.onerror = () => reject(reader.error); reader.onload = () => resolve(String(reader.result).split(",").at(-1) || ""); reader.readAsDataURL(blob); }); }
  async function compactImage(blob: Blob) { if (!blob.type.startsWith("image/")) return blob; try { const source = URL.createObjectURL(blob); const image = new Image(); await new Promise<void>((resolve, reject) => { image.onload = () => resolve(); image.onerror = () => reject(new Error("Image could not be compressed.")); image.src = source; }); const scale = Math.min(1, 1600 / Math.max(image.naturalWidth || 1, image.naturalHeight || 1)); const canvas = document.createElement("canvas"); canvas.width = Math.max(1, Math.round(image.naturalWidth * scale)); canvas.height = Math.max(1, Math.round(image.naturalHeight * scale)); canvas.getContext("2d")?.drawImage(image, 0, 0, canvas.width, canvas.height); URL.revokeObjectURL(source); const output = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, "image/webp", 0.78)); return output || blob; } catch { return blob; } }
  function assetExtension(file: Blob) { if (file.type === "image/webp") return "webp"; if (file.type === "application/pdf") return "pdf"; if (file.type === "audio/mpeg") return "mp3"; if (file.type === "audio/ogg") return "ogg"; if (file.type === "audio/wav") return "wav"; if (file.type === "audio/mp4" || file.type === "audio/x-m4a") return "m4a"; if (file.type.startsWith("audio/")) return "webm"; return "bin"; }
  async function cacheOfflineAsset(order: Order, kind: keyof OfflineMedia) { const response = await fetch(`${API}/orders/${encodeURIComponent(order.id)}/assets?kind=${kind === "shippingLabel" ? "shipping_label" : kind}`, { headers: { authorization: `Bearer ${session?.token || ""}` } }); if (!response.ok) return false; const original = await response.blob(); const file = kind === "photo" ? await compactImage(original) : original; await Filesystem.writeFile({ path: `meaningful-fulfilment/media/${order.id}/${kind}.${assetExtension(file)}`, data: await base64(file), directory: Directory.Data, recursive: true }); return true; }
  async function cacheManualAsset(url: string, path: string) { if (!url || url.startsWith("manual-order:") || Capacitor.getPlatform() === "web") return url; try { const response = await fetch(url); if (!response.ok) return url; const file = await response.blob(); const savedPath = `${path}.${assetExtension(file)}`; await Filesystem.writeFile({ path: savedPath, data: await base64(file), directory: Directory.Data, encoding: Encoding.UTF8, recursive: true }); const saved = await Filesystem.getUri({ path: savedPath, directory: Directory.Data }); return Capacitor.convertFileSrc(saved.uri); } catch { return url; } }
  async function cacheManualDetailAssets(detail: ManualDetail) { const voiceUrl = await cacheManualAsset(detail.voiceUrl, `meaningful-fulfilment/manual/${detail.intake.id}/voice`); const paymentReceipts = await Promise.all(detail.intake.paymentReceipts.map(async (receipt, index) => ({ ...receipt, url: await cacheManualAsset(receipt.url, `meaningful-fulfilment/manual/${detail.intake.id}/receipt-${index}`) }))); return { ...detail, voiceUrl, intake: { ...detail.intake, paymentReceipts } }; }
  async function cachedVoiceUrl(orderId: string) { if (Capacitor.getPlatform() === "web") return ""; for (const extension of ["webm", "mp3", "ogg", "wav", "m4a"]) try { const saved = await Filesystem.getUri({ path: `meaningful-fulfilment/media/${orderId}/voice.${extension}`, directory: Directory.Data }); return Capacitor.convertFileSrc(saved.uri); } catch { /* Try the next supported audio extension. */ } return ""; }
  function saveOrderDetail(detail: Detail) { setOrderDetailsCache((current) => { const next = { ...current, [detail.order.id]: detail }; save(ORDER_DETAILS_KEY, next); return next; }); }
  function saveManualDetail(detail: ManualDetail) { setManualDetailsCache((current) => { const next = { ...current, [detail.intake.id]: detail }; save(MANUAL_DETAILS_KEY, next); return next; }); }
  async function fetchOrderDetail(order: Order, persist = true) { if (!session) throw new Error("Sign in again to load this order."); const response = await fetch(`${API}/orders/${encodeURIComponent(order.id)}`, { headers: { authorization: `Bearer ${session.token}` } }); const data = await response.json(); if (!response.ok) throw new Error(data.error); const detail = data as Detail; if (persist) saveOrderDetail(detail); return detail; }
  async function getManualOrderDetails(id: string) { if (!session) throw new Error("Sign in again to load this Manual Order."); const response = await fetch(`${API}/manual-orders`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${session.token}` }, body: JSON.stringify({ action: "details", id }) }); const data = await response.json(); if (!response.ok) throw Error(data.error); return data.details as ManualDetail; }
  async function syncOfflineArchive(force = false) { if (!session || offlineSync.active) return; setOfflineSync({ active: true, completed: 0, total: 0, media: 0 }); try { const collected: Order[] = []; let page = 0; let total = 0; while (true) { const params = new URLSearchParams({ page: String(page), pageSize: String(PAGE_SIZE), status: "all", source: "all", includeTotal: page === 0 ? "1" : "0" }); const response = await fetch(`${API}/dashboard?${params}`, { cache: "no-store", headers: { authorization: `Bearer ${session.token}` } }); const data = await response.json(); if (!response.ok) throw Error(data.error); collected.push(...(data.orders || [])); total = Number(data.totalCount || total || collected.length); const progress: Dashboard = { counts: data.counts || {}, orders: [...collected], totalCount: total, hasMore: Boolean(data.hasMore), latestUpdatedAt: collected[0]?.updatedAt || null, savedAt: Date.now() }; setDashboard(progress); save(DASHBOARD_KEY, progress); setOfflineSync((current) => ({ ...current, total, completed: collected.length })); if (!data.hasMore) break; page += 1; }
      const completeDashboard: Dashboard = { counts: {}, orders: collected, totalCount: total, hasMore: false, latestUpdatedAt: collected[0]?.updatedAt || null, savedAt: Date.now() };
      const details = { ...orderDetailsCache }; const changedOrders = collected.filter((order) => force || !details[order.id] || details[order.id].order.updatedAt !== order.updatedAt); let detailIndex = 0; const workers = Array.from({ length: Math.min(4, changedOrders.length) }, async () => { while (detailIndex < changedOrders.length) { const order = changedOrders[detailIndex++]; try { details[order.id] = await fetchOrderDetail(order, false); } catch { /* One unavailable order must not stop the archive. */ } } }); await Promise.all(workers); setOrderDetailsCache(details); save(ORDER_DETAILS_KEY, details);
      const manualResponse = await fetch(`${API}/manual-orders`, { cache: "no-store", headers: { authorization: `Bearer ${session.token}` } }); const manualData = await manualResponse.json(); if (!manualResponse.ok) throw Error(manualData.error); const allManual: ManualOrder[] = Array.isArray(manualData.intakes) ? manualData.intakes as ManualOrder[] : []; const approvals = allManual.filter((order) => order.status === "awaiting_payment"); const history = allManual.filter((order) => order.status !== "awaiting_payment"); setManualOrders(approvals); setManualHistory(history); setManualCacheReady(true); save(MANUAL_APPROVALS_KEY, approvals); save(MANUAL_HISTORY_KEY, history); save(MANUAL_SAVED_AT_KEY, Date.now());
      const manualDetails = { ...manualDetailsCache }; const changedManualOrders = allManual.filter((order) => force || !manualDetails[order.id] || manualDetails[order.id].intake.updatedAt !== order.updatedAt); let manualIndex = 0; const manualWorkers = Array.from({ length: Math.min(4, changedManualOrders.length) }, async () => { while (manualIndex < changedManualOrders.length) { const order = changedManualOrders[manualIndex++]; try { manualDetails[order.id] = await cacheManualDetailAssets(await getManualOrderDetails(order.id)); } catch { /* Keep the rest of the transaction archive available. */ } } }); await Promise.all(manualWorkers); setManualDetailsCache(manualDetails); save(MANUAL_DETAILS_KEY, manualDetails);
      let report = salesReport; if (force && session.role === "admin") { try { const response = await fetch(`${API}/reports?source=all`, { cache: "no-store", headers: { authorization: `Bearer ${session.token}` } }); const data = await response.json(); if (response.ok) { report = { ...data, savedAt: Date.now() }; setSalesReport(report); save(REPORT_KEY, report); } } catch { /* The saved report remains available. */ } }
      const mediaCache = stored<Record<string, string>>(OFFLINE_MEDIA_KEY, {}); let media = 0; for (const order of collected) for (const kind of ["voice", "photo", "attachment", "shippingLabel"] as const) { const mediaKey = `${order.id}:${kind}`; const version = String(order.updatedAt || ""); if (order.offlineMedia?.[kind] && (force || mediaCache[mediaKey] !== version) && await cacheOfflineAsset(order, kind)) { mediaCache[mediaKey] = version; media += 1; setOfflineSync((current) => ({ ...current, media })); } } save(OFFLINE_MEDIA_KEY, mediaCache);
      setDashboard(completeDashboard); save(DASHBOARD_KEY, completeDashboard); await saveOfflineArchive({ version: 3, dashboard: completeDashboard, orderDetails: details, manualOrders: approvals, manualHistory: history, manualDetails, salesReport: report, savedAt: Date.now() }); save(LAST_OFFLINE_SYNC_KEY, Date.now()); const changed = changedOrders.length + changedManualOrders.length; setNotice(`Offline archive refreshed: ${changed} changed records and ${media} changed files. All saved data remains available on this phone.`); } catch (error) { setNotice(error instanceof Error ? error.message : "Could not complete the offline sync."); } finally { setOfflineSync((current) => ({ ...current, active: false })); } }
  async function fetchPage(page: number, replace = false) {
    if (!session) return;
    const params = orderFilters(); params.set("page", String(page));
    const response = await fetch(`${API}/dashboard?${params}`, { cache: "no-store", headers: { authorization: `Bearer ${session.token}` } });
    const data = await response.json(); if (!response.ok) throw new Error(data.error);
    const fresh: Dashboard = { counts: data.counts || {}, orders: replace ? data.orders || [] : [...dashboard.orders, ...(data.orders || [])], totalCount: data.totalCount || 0, hasMore: data.hasMore === true, latestUpdatedAt: data.latestUpdatedAt || null, savedAt: Date.now() };
    setDashboard(fresh); save(DASHBOARD_KEY, fresh); setUpdatesAvailable(false); setNotice("");
  }
  async function refresh(force = false) { if (!session || !archiveLoaded.current || (!force && dashboard.savedAt && Date.now() - dashboard.savedAt < CACHE_MAX_AGE)) return; const completeArchive = !dashboard.hasMore && dashboard.totalCount > 0 && dashboard.orders.length >= dashboard.totalCount && statusFilter === "all" && sourceFilter === "all" && !fromDate && !toDate; if (completeArchive) { await checkForUpdates(); return; } setBusy(true); try { await fetchPage(0, true); } catch (error) { const message = error instanceof Error ? error.message : "Could not load orders."; if (message.includes("REQUIRED")) { localStorage.removeItem(SESSION_KEY); setSession(null); } else setNotice(message); } finally { setBusy(false); } }
  async function checkForUpdates() {
    if (!session || document.visibilityState !== "visible") return;
    try {
      const response = await fetch(`${API}/dashboard?check=1`, { cache: "no-store", headers: { authorization: `Bearer ${session.token}` } });
      const data = await response.json();
      if (!response.ok) return;
      if ((dashboard.latestUpdatedAt && data.latestUpdatedAt && data.latestUpdatedAt !== dashboard.latestUpdatedAt) || Number(data.totalCount || 0) > dashboard.totalCount) setUpdatesAvailable(true);
    } catch { /* Existing saved orders remain available when temporarily offline. */ }
  }
  useEffect(() => { void loadOfflineArchive(); }, []);
  useEffect(() => {
    if (!session || !archiveReady || autoSyncFrequency === "manual") return;
    const delay = autoSyncFrequency === "hourly" ? 60 * 60 * 1000 : autoSyncFrequency === "daily" ? 24 * 60 * 60 * 1000 : 0;
    const runIfDue = () => { const last = stored<number>(LAST_OFFLINE_SYNC_KEY, 0); if (!last || !delay || Date.now() - last >= delay) void syncOfflineArchive(false); };
    runIfDue();
    if (!delay) return;
    const timer = window.setInterval(runIfDue, Math.min(delay, 15 * 60 * 1000));
    return () => window.clearInterval(timer);
  }, [session?.token, archiveReady, autoSyncFrequency]);
  useEffect(() => {
    // Saved orders render before any network request. The quiet check only
    // decides whether to show the "Refresh now" banner.
    const firstCheck = window.setTimeout(() => void checkForUpdates(), 500);
    const interval = window.setInterval(() => void checkForUpdates(), 30000);
    const onVisible = () => { if (document.visibilityState === "visible") void checkForUpdates(); };
    document.addEventListener("visibilitychange", onVisible);
    return () => { window.clearTimeout(firstCheck); window.clearInterval(interval); document.removeEventListener("visibilitychange", onVisible); };
  }, [session?.token, dashboard.latestUpdatedAt, dashboard.totalCount, archiveReady]);
  useEffect(() => { if (!session || !archiveReady) return; if (workspace === "reports") { void loadSalesReport(); return; } if (workspace !== "fulfilment") return; if (initialWorkspaceLoad.current) { initialWorkspaceLoad.current = false; if (!dashboard.orders.length) void refresh(); return; } void refresh(); }, [session?.token, workspace, statusFilter, sourceFilter, fromDate, toDate, archiveReady]);
  useEffect(() => { if (session && workspace === "updates") void loadUpdateRelease(); }, [session?.token, workspace]);
  useEffect(() => {
    let startY = 0;
    const start = (event: TouchEvent) => { if (window.scrollY <= 0 && !busy) startY = event.touches[0]?.clientY || 0; };
    const move = (event: TouchEvent) => { if (!startY || window.scrollY > 0) return; setPullDistance(Math.min(90, Math.max(0, (event.touches[0]?.clientY || 0) - startY))); };
    const end = () => { const shouldRefresh = pullDistance >= 56; startY = 0; setPullDistance(0); if (shouldRefresh) void refresh(true); };
    window.addEventListener("touchstart", start, { passive: true });
    window.addEventListener("touchmove", move, { passive: true });
    window.addEventListener("touchend", end, { passive: true });
    return () => { window.removeEventListener("touchstart", start); window.removeEventListener("touchmove", move); window.removeEventListener("touchend", end); };
  }, [busy, pullDistance, session?.token]);
  useEffect(() => {
    if (!session || Capacitor.getPlatform() === "web") return;
    const activeSession = session;
    let cancelled = false;
    let registrationListener: Awaited<ReturnType<typeof PushNotifications.addListener>> | undefined;
    let receivedListener: Awaited<ReturnType<typeof PushNotifications.addListener>> | undefined;
    let actionListener: Awaited<ReturnType<typeof PushNotifications.addListener>> | undefined;

    async function registerDevice(token: string) {
      const response = await fetch(`${API}/notifications/register`, {
        method: "POST",
        headers: { "content-type": "application/json", authorization: `Bearer ${activeSession.token}` },
        body: JSON.stringify({ token, platform: Capacitor.getPlatform() }),
      });
      if (!response.ok) throw new Error("Could not enable notifications on this device.");
    }

    async function setUpNotifications() {
      try {
        registrationListener = await PushNotifications.addListener("registration", (token) => {
          if (!cancelled) void registerDevice(token.value).catch(() => setNotice("Notifications could not be enabled. Try reopening the app."));
        });
        receivedListener = await PushNotifications.addListener("pushNotificationReceived", (notification) => {
          if (!cancelled) setNotice(notification.body || notification.title || "A new Manual Order was received.");
        });
        actionListener = await PushNotifications.addListener("pushNotificationActionPerformed", () => {
          if (cancelled) return;
          setWorkspace("manual_orders");
          void loadManualApprovals();
        });
        const permission = await PushNotifications.checkPermissions();
        const result = permission.receive === "prompt" ? await PushNotifications.requestPermissions() : permission;
        if (result.receive === "granted") await PushNotifications.register();
      } catch {
        if (!cancelled) setNotice("Notifications are unavailable on this device.");
      }
    }

    void setUpNotifications();
    return () => {
      cancelled = true;
      registrationListener?.remove();
      receivedListener?.remove();
      actionListener?.remove();
    };
  }, [session?.token]);
  async function login(event: React.FormEvent) { event.preventDefault(); setBusy(true); try { const response = await fetch(`${API}/login`, { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ username, password }) }); const data = await response.json(); if (!response.ok) throw Error(data.error); setSession(data); save(SESSION_KEY, data); setPassword(""); setNotice(""); } catch (error) { setNotice(error instanceof Error ? error.message : "Unable to sign in."); } finally { setBusy(false); } }
  async function loadMore() { if (!session || loadingMore || !dashboard.hasMore) return; setLoadingMore(true); try { await fetchPage(Math.floor(dashboard.orders.length / PAGE_SIZE), false); } catch (error) { setNotice(error instanceof Error ? error.message : "Could not load more orders."); } finally { setLoadingMore(false); } }
  async function openOrder(id: string) { if (!session) return; setNotice(""); const cached = orderDetailsCache[id]; if (cached) { const localVoice = cached.details.voice ? await cachedVoiceUrl(id) : ""; const detail = localVoice ? { ...cached, details: { ...cached.details, voice: { ...cached.details.voice!, url: localVoice } } } : cached; setSelected(detail); return; } setOpening(true); try { const order = dashboard.orders.find((item) => item.id === id); if (!order) throw new Error("Order is no longer in the saved archive."); const data = await fetchOrderDetail(order); const localVoice = data.details?.voice ? await cachedVoiceUrl(id) : ""; if (localVoice && data.details.voice) data.details.voice.url = localVoice; setSelected(data); } catch (error) { setNotice(error instanceof Error ? error.message : "Could not open this order."); } finally { setOpening(false); } }
  async function lookup(code: string) { if (!session || !code) return; setBusy(true); try { const response = await fetch(`${API}/orders/lookup?code=${encodeURIComponent(code)}`, { headers: { authorization: `Bearer ${session.token}` } }); const data = await response.json(); if (!response.ok) throw Error(data.error); if (!data.order) throw Error("No order matches this code."); await openOrder(data.order.id); } catch (error) { setNotice(error instanceof Error ? error.message : "Could not find this order."); } finally { setBusy(false); } }
  async function scan() { try { const result = await CapacitorBarcodeScanner.scanBarcode({ hint: CapacitorBarcodeScannerTypeHint.ALL, scanInstructions: "Scan the order barcode or QR code" }); if (result.ScanResult) await lookup(result.ScanResult); } catch { setNotice("The camera scanner could not start. You can enter the code manually."); } }
  async function advance() { if (!session || !selected || !next[selected.order.status]) return; setBusy(true); try { const response = await fetch(`${API}/orders/transition`, { method: "POST", headers: { "content-type": "application/json", authorization: `Bearer ${session.token}` }, body: JSON.stringify({ orderId: selected.order.id, fromStatus: selected.order.status, toStatus: next[selected.order.status] }) }); const data = await response.json(); if (!response.ok) throw Error(data.error === "ORDER_CHANGED" ? "This order changed on another device. Open it again." : data.error); setSelected({ ...selected, order: data.order }); const fresh = { ...dashboard, orders: dashboard.orders.map((item) => item.id === data.order.id ? data.order : item), savedAt: Date.now() }; setDashboard(fresh); save(DASHBOARD_KEY, fresh); } catch (error) { setNotice(error instanceof Error ? error.message : "Could not update this order."); } finally { setBusy(false); } }
  async function loadManualOrders(showLoading = true) { if (!session) return; if (showLoading) setBusy(true); try { const response = await fetch(`${API}/manual-orders`, { cache: "no-store", headers: { authorization: `Bearer ${session.token}` } }); const data = await response.json(); if (!response.ok) throw Error(data.error); const all: ManualOrder[] = Array.isArray(data.intakes) ? data.intakes as ManualOrder[] : []; const approvals = all.filter((order) => order.status === "awaiting_payment"); const history = all.filter((order) => order.status !== "awaiting_payment"); setManualOrders(approvals); setManualHistory(history); setManualCacheReady(true); save(MANUAL_APPROVALS_KEY, approvals); save(MANUAL_HISTORY_KEY, history); save(MANUAL_SAVED_AT_KEY, Date.now()); } catch (error) { if (showLoading) setNotice(error instanceof Error ? error.message : "Could not load Manual Orders."); } finally { if (showLoading) setBusy(false); } }
  async function refreshManualOrdersIfStale() { if (!manualCacheReady) { await loadManualOrders(); return; } if (Date.now() - stored<number>(MANUAL_SAVED_AT_KEY, 0) >= CACHE_MAX_AGE) void loadManualOrders(false); }
  async function loadManualApprovals() { await refreshManualOrdersIfStale(); }
  async function loadManualHistory() { await refreshManualOrdersIfStale(); }
  async function loadSalesReport() { if (!session || session.role !== "admin") return; setReportLoading(true); try { const params = new URLSearchParams({ source: sourceFilter }); if (fromDate) params.set("from", fromDate); if (toDate) params.set("to", toDate); const response = await fetch(`${API}/reports?${params}`, { cache: "no-store", headers: { authorization: `Bearer ${session.token}` } }); const data = await response.json(); if (!response.ok) throw Error(data.error); const fresh = { ...data, savedAt: Date.now() }; setSalesReport(fresh); save(REPORT_KEY, fresh); } catch (error) { setNotice(error instanceof Error ? error.message : "Could not load sales reporting."); } finally { setReportLoading(false); } }
  async function loadUpdateRelease() { try { const response = await fetch(UPDATE_API, { headers: { accept: "application/vnd.github+json" } }); const data = await response.json(); if (!response.ok) throw Error("Could not check the latest release."); const body = String(data.body || ""); const version = body.match(/version\s+([\d.]+)/i)?.[1] || String(data.tag_name || "Latest"); const asset = data.assets?.find((item: { name?: string; label?: string }) => /\.apk$/i.test(String(item.name || ""))); setUpdateRelease({ version, releasedAt: String(data.published_at || data.created_at || ""), downloadUrl: String(asset?.browser_download_url || UPDATE_URL), fileName: String(asset?.label || asset?.name || "Meaningful Fulfilment patch.apk") }); } catch { setUpdateRelease(null); } }
  async function downloadAndInstallUpdate() { if (!updateRelease || updateDownloading) return; if (Capacitor.getPlatform() === "web") { window.open(updateRelease.downloadUrl, "_blank", "noopener"); return; } setUpdateDownloading(true); try { await InAppUpdate.downloadAndInstall({ url: updateRelease.downloadUrl, fileName: updateRelease.fileName || `Meaningful Fulfilment patch ${updateRelease.version}.apk` }); setNotice("Update downloaded. Android is ready for you to confirm installation."); } catch (error) { setNotice(error instanceof Error ? error.message : "The update could not be downloaded."); } finally { setUpdateDownloading(false); } }
  async function openManualOrder(id: string) { if (!session) return; setOpening(true); try { const cached = manualDetailsCache[id]; if (cached) { setManualDetail(cached); return; } const detail = await getManualOrderDetails(id); saveManualDetail(detail); setManualDetail(detail); } catch (error) { setNotice(error instanceof Error ? error.message : "Could not open this Manual Order."); } finally { setOpening(false); } }
  async function chooseWorkspace(item: Workspace) { setWorkspace(item); setWorkspaceOpen(false); setNotice(""); if (item === "manual_orders") { setManualPage("approvals"); void loadManualApprovals(); } if (item === "fulfilment") void refresh(); }
  function signOut() { localStorage.removeItem(SESSION_KEY); setSession(null); }
  const name = workspace === "fulfilment" ? "Fulfilment" : workspace === "manual_orders" ? "Manual Orders" : workspace === "reports" ? "Reports" : "Updates";
  if (opening && workspace === "manual_orders") return <main aria-live="polite" style={{ display: "grid", minHeight: "100vh", placeItems: "center", background: "linear-gradient(145deg, #f1faf7, #f6f6f7)", textAlign: "center" }}><div style={{ display: "grid", justifyItems: "center", gap: 14, maxWidth: 330, padding: "30px 24px", background: "#fff", border: "1px solid #d9ebe5", borderRadius: 16, boxShadow: "0 12px 32px #00806016" }}><svg aria-hidden="true" width="46" height="46" viewBox="0 0 46 46"><circle cx="23" cy="23" r="18" fill="none" stroke="#d9f2ed" strokeWidth="5" /><path d="M23 5a18 18 0 0 1 18 18" fill="none" stroke="#008060" strokeWidth="5" strokeLinecap="round"><animateTransform attributeName="transform" type="rotate" from="0 23 23" to="360 23 23" dur="0.8s" repeatCount="indefinite" /></path></svg><h1 style={{ fontSize: 23 }}>Opening order</h1><p>Loading the customer details, customisation, voice message, and payment information.</p></div></main>;
  const picker = <div className="workspace-control"><button className="workspace-trigger" onClick={() => setWorkspaceOpen((open) => !open)} aria-expanded={workspaceOpen}><span>{name}</span><b>⌄</b></button>{workspaceOpen && <div className="workspace-menu"><button className={workspace === "fulfilment" ? "active" : ""} onClick={() => void chooseWorkspace("fulfilment")}><strong>Fulfilment</strong><small>Orders and production</small></button>{session?.role === "admin" && <><button className={workspace === "manual_orders" ? "active" : ""} onClick={() => void chooseWorkspace("manual_orders")}><strong>Manual Orders</strong><small>Payment approvals</small></button><button className={workspace === "reports" ? "active" : ""} onClick={() => void chooseWorkspace("reports")}><strong>Reports</strong><small>Sales and cash collected</small></button></>}<button className={workspace === "updates" ? "active" : ""} onClick={() => void chooseWorkspace("updates")}><strong>Updates</strong><small>Install the latest app</small></button></div>}</div>;

  if (!session) return <main className="login"><img className="brand-logo brand-logo-login" src="/meaningful-plushies-logo.png" alt="Meaningful Plushies" /><h1>Meaningful Fulfilment</h1><p>Sign in to your warehouse workspace.</p><form onSubmit={login}><label>Username<input value={username} onChange={(event) => setUsername(event.target.value)} autoComplete="username" /></label><label>Password<input value={password} onChange={(event) => setPassword(event.target.value)} type="password" autoComplete="current-password" /></label><button disabled={busy}>{busy ? "Signing in…" : "Sign in"}</button></form>{notice && <p className="error">{notice}</p>}</main>;
  if (selected) return <main><header className="topbar"><div>{picker}<button className="back" onClick={() => setSelected(null)}>‹ Back to orders</button></div><img className="brand-logo" src="/meaningful-plushies-logo.png" alt="Meaningful Plushies" /></header><div className="detail-title"><div><span className="eyebrow">ORDER</span><h1>#{selected.order.orderNumber}</h1><span className={`status status-${selected.order.status}`}>{labels[selected.order.status] || selected.order.status}</span></div><button className="quiet" onClick={() => void refresh(true)}>Refresh</button></div><section className="card"><h2>{selected.order.plushName || selected.order.product || "Meaningful Plushie"}</h2><p>{selected.order.character || "Character not set"} · {selected.order.voiceLength || 0} seconds</p>{selected.details.voice ? <div className="voice-card"><strong>Voice message</strong><small>{selected.details.voice.fileName}</small><audio controls preload="metadata" src={selected.details.voice.url} /></div> : <p className="muted">No playable voice message is available.</p>}</section><section className="card"><h2>Payment</h2><div className="detail-grid"><div><span>Total paid</span><strong>{money.format(selected.order.totalAmount || 0)}</strong></div><div><span>Method</span><strong>{selected.order.paymentProcessor || "—"}</strong></div><div><span>Subtotal</span><strong>{money.format(selected.details.subtotalAmount || 0)}</strong></div><div><span>Shipping</span><strong>{money.format(selected.details.shippingAmount || 0)}</strong></div><div><span>Discount</span><strong>{money.format(selected.details.discountAmount || 0)}</strong></div><div><span>Outstanding</span><strong>{money.format(selected.details.outstandingBalance || 0)}</strong></div></div></section><section className="card"><h2>Customer</h2><p><strong>{selected.order.customerName || "—"}</strong><br />{selected.order.phone || "No phone"}<br />{selected.details.email || "No email"}</p><p>{selected.order.address || "No delivery address"}</p></section><section className="card"><h2>Plushie details</h2><div className="detail-grid"><div><span>Name</span><strong>{selected.order.plushName || "—"}</strong></div><div><span>Gender</span><strong>{selected.details.plushGender || "—"}</strong></div><div><span>Born on</span><strong>{selected.details.plushBirthDate || "—"}</strong></div><div><span>Belongs to</span><strong>{selected.details.plushBelongsTo || "—"}</strong></div></div>{selected.details.meaningfulNote && <p className="note">{selected.details.meaningfulNote}</p>}</section><section className="card"><h2>Delivery</h2><div className="detail-grid"><div><span>Courier</span><strong>{selected.order.courier || "—"}</strong></div><div><span>Tracking</span><strong>{selected.order.trackingNumber || "—"}</strong></div></div></section>{next[selected.order.status] && <button className="primary-action" disabled={busy} onClick={() => void advance()}>{busy ? "Updating…" : `Move to ${labels[next[selected.order.status]]}`}</button>}{notice && <p className="error">{notice}</p>}</main>;
  if (manualDetail) return <main><header className="topbar"><div>{picker}<button className="back" onClick={() => setManualDetail(null)}>‹ Back to Manual Orders</button></div><img className="brand-logo" src="/meaningful-plushies-logo.png" alt="Meaningful Plushies" /></header><div className="detail-title"><div><span className="eyebrow">MANUAL ORDER</span><h1>{manualDetail.intake.customerName || "Customer"}</h1><p>{manualStatus(manualDetail.intake)}</p></div></div><section className="card"><h2>Order</h2><p><strong>{manualDetail.intake.character} · {manualDetail.intake.productDisplayName}</strong><br />Submitted {date(manualDetail.intake.createdAt)}<br />{manualDetail.intake.shopifyOrderName || "Not created in Shopify yet"}</p></section><section className="card"><h2>Customer and delivery</h2><p><strong>{manualDetail.intake.customerName}</strong><br />{manualDetail.intake.phoneOriginal}<br />{manualDetail.intake.customerEmail}</p><p>{manualAddress(manualDetail.intake)}</p></section><section className="card"><h2>Customisation</h2><div className="detail-grid"><div><span>Plush name</span><strong>{manualDetail.form?.plushName || "—"}</strong></div><div><span>Gender</span><strong>{manualDetail.form?.gender || "—"}</strong></div><div><span>Born on</span><strong>{manualDetail.form?.birthDate || "—"}</strong></div><div><span>Belongs to</span><strong>{manualDetail.form?.belongsTo || "—"}</strong></div></div>{manualDetail.form?.meaningfulNote && <p className="note">{manualDetail.form.meaningfulNote}</p>}{manualDetail.voiceUrl && <div className="voice-card"><strong>Voice message</strong><small>{manualDetail.voiceFileName || "Voice message"}</small><audio controls src={manualDetail.voiceUrl} /></div>}</section><section className="card"><h2>Payment</h2><p><strong>{manualStatus(manualDetail.intake)}</strong><br />{manualDetail.intake.paymentApprovedAt ? `Approved ${date(manualDetail.intake.paymentApprovedAt)}` : "No receipt approved yet"}</p>{manualDetail.intake.paymentReceipts.filter((receipt) => !receipt.url.startsWith("manual-order:")).map((receipt) => <a className="receipt-link" key={receipt.url} href={receipt.url} target="_blank" rel="noreferrer">Open receipt: {receipt.fileName || "Receipt"}</a>)}</section>{notice && <p className="error">{notice}</p>}</main>;
  if (workspace === "updates") return <main><header className="topbar"><div>{picker}<p className="eyebrow">MOBILE APP</p><h1>Updates</h1></div><button className="avatar" onClick={signOut}>{session.displayName.slice(0, 1).toUpperCase()}</button></header><section className="card update-card"><span className="update-dot" /><div><h2>Latest mobile app</h2><p>Download the newest version when an update is available.</p></div><div className="detail-grid"><div><span>Patch version</span><strong>{updateRelease ? `v${updateRelease.version}` : "Checking…"}</strong></div><div><span>Released</span><strong>{updateRelease ? exactTime(updateRelease.releasedAt) : "Checking…"}</strong></div></div><button className="update-button" disabled={!updateRelease || updateDownloading} onClick={() => void downloadAndInstallUpdate()}>{updateDownloading ? "Downloading update…" : "Download and install in app"}</button><small>{updateRelease?.fileName ? `File: ${updateRelease.fileName}. ` : ""}The release time is shown in Malaysia time. Android will ask you to confirm installation; your saved sign-in and order cache stay on your phone.</small></section><section className="card update-card"><div><h2>Offline archive</h2><p>Save every order, voice message, photo, PDF, and shipping label to this phone. Images are compressed only in the phone copy; cloud originals stay unchanged. Automatic refreshes download only records or files that changed.</p></div><label className="offline-frequency">Automatic download<select value={autoSyncFrequency} onChange={(event) => { const frequency = event.target.value as AutoSyncFrequency; setAutoSyncFrequency(frequency); save(AUTO_SYNC_KEY, frequency); }}><option value="open">Every time I open the app</option><option value="hourly">Every hour while the app is open</option><option value="daily">Once a day while the app is open</option><option value="manual">Manual only</option></select></label><button className="update-button" disabled={offlineSync.active} onClick={() => void syncOfflineArchive(true)}>{offlineSync.active ? `Saving ${offlineSync.completed}/${offlineSync.total || "…"} orders · ${offlineSync.media} files` : "Save complete offline archive"}</button><small>{offlineSync.active ? "Keep the app open and connected while the first archive is created." : "The archive stays on this phone. A full save also refreshes the reporting snapshot."}</small></section>{notice && <p className="error">{notice}</p>}</main>;
  if (workspace === "manual_orders") return <main><header className="topbar"><div>{picker}<p className="eyebrow">MANUAL ORDERS</p><h1>{manualPage === "approvals" ? "Payment approvals" : "Transaction history"}</h1><p>{manualPage === "approvals" ? `${manualOrders.length} awaiting approval` : `${manualHistory.length} completed records`}</p></div><button className="avatar" onClick={signOut}>{session.displayName.slice(0, 1).toUpperCase()}</button></header><div className="workspace-tabs"><button className={manualPage === "approvals" ? "active" : ""} onClick={() => { setManualPage("approvals"); void loadManualApprovals(); }}>Awaiting approval</button><button className={manualPage === "history" ? "active" : ""} onClick={() => { setManualPage("history"); void loadManualHistory(); }}>Transaction history</button></div>{manualPage === "approvals" ? <section className="order-list"><div className="list-heading"><h2>Awaiting approval</h2><span>{manualOrders.length}</span></div>{manualOrders.map((order) => <button className="order-row manual-approval-row" key={order.id} onClick={() => void openManualOrder(order.id)}><div><strong>{order.customerName || "Customer"}</strong><span>{order.character} · {order.speakerSeconds || 0} seconds · {order.shippingRegion === "EAST" ? "East Malaysia" : "West Malaysia"}</span><small>{order.phoneOriginal}</small><small>Reference: {order.reference || `MP-${order.id.toUpperCase()}`}</small><small className="collect">To collect: {order.amountToCollect === null || order.amountToCollect === undefined ? "Price unavailable" : money.format(order.amountToCollect)}{order.shippingRegion === "EAST" ? " · includes East Malaysia delivery" : ""}</small></div><div><span className="status status-awaiting_customisation">Awaiting payment</span><b>›</b></div></button>)}{!manualOrders.length && <p className="empty">No orders are awaiting approval.</p>}</section> : <section className="order-list"><div className="list-heading"><h2>Transaction history</h2><span>{manualHistory.length}</span></div>{manualHistory.map((order) => <button className="order-row" key={order.id} onClick={() => void openManualOrder(order.id)}><div><strong>{order.customerName || "Customer"}</strong><span>{order.shopifyOrderName || order.productDisplayName}</span><small>{order.paymentApprovedAt ? `Approved ${date(order.paymentApprovedAt)}` : date(order.createdAt)}</small></div><div><span className="status status-packed">{manualStatus(order)}</span><b>›</b></div></button>)}{!manualHistory.length && !busy && <p className="empty">No transaction history yet.</p>}</section>}{notice && <p className="error">{notice}</p>}</main>;
  if (workspace === "reports") return <main><header className="topbar"><div>{picker}<p className="eyebrow">REPORTING</p><h1>Sales report</h1><p>{salesReport?.savedAt ? `Last updated ${new Date(salesReport.savedAt).toLocaleTimeString("en-MY", { hour: "2-digit", minute: "2-digit" })}` : "Preparing your first report…"}</p></div><button className="avatar" onClick={signOut}>{session.displayName.slice(0, 1).toUpperCase()}</button></header><section className="card mobile-filters"><div className="filter-heading"><h2>Report filters</h2><button className="quiet" onClick={() => { setSourceFilter("all"); setFromDate(""); setToDate(""); void loadSalesReport(); }}>Clear</button></div><div className="filter-grid"><label>From<input type="date" value={fromDate} onChange={(event) => setFromDate(event.target.value)} /></label><label>To<input type="date" value={toDate} onChange={(event) => setToDate(event.target.value)} /></label><label>Source<select value={sourceFilter} onChange={(event) => setSourceFilter(event.target.value as SourceFilter)}><option value="all">All sources</option><option value="shopify">Shopify</option><option value="tiktok">TikTok Shop</option></select></label></div></section><section className="card mobile-report"><div className="filter-heading"><div><h2>Sales reporting</h2><p>{salesReport ? `${salesReport.orderCount} sales in this range` : "Calculating in the background…"}</p></div><button className="quiet" disabled={reportLoading} onClick={() => void loadSalesReport()}>{reportLoading ? "Refreshing…" : "Refresh"}</button></div>{salesReport && <><div className="report-channel"><span>Shopify <b>{salesReport.channel.shopify.count} sales</b><strong>{money.format(salesReport.channel.shopify.sales)}</strong></span><span>TikTok Shop <b>{salesReport.channel.tiktok.count} sales</b><strong>{money.format(salesReport.channel.tiktok.sales)}</strong></span></div><div className="report-metrics"><span>Total sales<strong>{money.format(salesReport.sales.gross)}</strong></span><span>Collected<strong>{money.format(salesReport.sales.totalCollected)}</strong></span><span>Discounts<strong>{money.format(salesReport.sales.productDiscounted + salesReport.sales.shippingDiscounted)}</strong></span><span>Fees<strong>{money.format(salesReport.sales.totalFees)}</strong></span><span>Cash after fees<strong>{money.format(salesReport.sales.collected)}</strong></span></div></>}<p>{reportLoading ? "Your saved report remains visible while the latest figures are calculated." : "Reporting is refreshed only in this workspace, so opening Orders stays fast."}</p></section>{notice && <p className="error">{notice}</p>}</main>;
  return <main><style>{`.mobile-report{display:none}`}</style>
    <div className={`pull-to-refresh ${pullDistance ? "visible" : ""}`} style={{ height: pullDistance }} aria-hidden="true">{pullDistance >= 56 ? "Release to refresh" : "Pull down to refresh"}</div>
    <header className="topbar"><div>{picker}<p className="eyebrow">FULFILMENT</p><h1>Orders</h1><p>{dashboard.orders.length} of {dashboard.totalCount || "…"} orders loaded</p></div><button className="avatar" onClick={signOut}>{session.displayName.slice(0, 1).toUpperCase()}</button></header>
    {updatesAvailable && <button className="updates-banner" onClick={() => void refresh(true)} disabled={busy}><span>New orders or changes are ready.</span><strong>{busy ? "Refreshing…" : "Refresh now"}</strong></button>}
    <section className="card mobile-filters"><div className="filter-heading"><h2>Filters</h2><button className="quiet" onClick={() => { setStatusFilter("all"); setSourceFilter("all"); setFromDate(""); setToDate(""); }}>Clear</button></div><div className="filter-grid"><label>From<input type="date" value={fromDate} onChange={(event) => setFromDate(event.target.value)} /></label><label>To<input type="date" value={toDate} onChange={(event) => setToDate(event.target.value)} /></label><label>Source<select value={sourceFilter} onChange={(event) => setSourceFilter(event.target.value as SourceFilter)}><option value="all">All sources</option><option value="shopify">Shopify</option><option value="tiktok">TikTok Shop</option></select></label><label>Status<select value={statusFilter} onChange={(event) => setStatusFilter(event.target.value)}><option value="all">All statuses</option>{Object.entries(labels).map(([value, label]) => <option key={value} value={value}>{label}</option>)}</select></label></div></section>
    {session.role === "admin" && <section className="card mobile-report"><div className="filter-heading"><div><h2>Sales reporting</h2><p>{salesReport ? `${salesReport.orderCount} sales in this range` : "Loading reporting…"}</p></div><button className="quiet" disabled={reportLoading} onClick={() => void loadSalesReport()}>{reportLoading ? "Loading…" : "Refresh"}</button></div>{salesReport && <><div className="report-channel"><span>Shopify <b>{salesReport.channel.shopify.count} sales</b><strong>{money.format(salesReport.channel.shopify.sales)}</strong></span><span>TikTok Shop <b>{salesReport.channel.tiktok.count} sales</b><strong>{money.format(salesReport.channel.tiktok.sales)}</strong></span></div><div className="report-metrics"><span>Total sales<strong>{money.format(salesReport.sales.gross)}</strong></span><span>Collected<strong>{money.format(salesReport.sales.totalCollected)}</strong></span><span>Discounts<strong>{money.format(salesReport.sales.productDiscounted + salesReport.sales.shippingDiscounted)}</strong></span><span>Fees<strong>{money.format(salesReport.sales.totalFees)}</strong></span><span>Cash after fees<strong>{money.format(salesReport.sales.collected)}</strong></span></div></>}</section>}
    <div className="metrics"><article><span>New</span><strong>{dashboard.counts.new_order || 0}</strong></article><article><span>In production</span><strong>{dashboard.counts.sent_for_sewing || 0}</strong></article><article><span>Packed</span><strong>{dashboard.counts.packed || 0}</strong></article></div>
    <div className="toolbar"><button className="scan" onClick={scan} disabled={busy}>Scan order</button><button className="quiet refresh" onClick={() => void refresh(true)} disabled={busy}>{busy ? "Refreshing…" : "Refresh"}</button></div>
    <form className="search" onSubmit={(event) => { event.preventDefault(); void lookup(new FormData(event.currentTarget).get("code") as string); }}><input name="code" placeholder="Search order number" /><button disabled={busy}>Search</button></form>
    <section className="order-list"><div className="list-heading"><h2>All orders</h2><span>{dashboard.totalCount}</span></div>{dashboard.orders.map((order) => <button className="order-row" key={order.id} onClick={() => void openOrder(order.id)}><div><strong>#{order.orderNumber}</strong><span>{order.customerName || "Customer"} · {order.plushName || order.product || "Plushie"}</span><small>{date(order.orderDate)}</small></div><div><span className={`status status-${order.status}`}>{labels[order.status] || order.status}</span><b>›</b></div></button>)}{!dashboard.orders.length && <p className="empty">No saved orders yet. Pull down or tap Refresh while connected.</p>}{dashboard.hasMore && <button className="load-more" onClick={() => void loadMore()} disabled={loadingMore}>{loadingMore ? "Loading orders…" : "Load next 100 orders"}</button>}</section>
    {opening && <div className="loading">Opening order…</div>}{notice && <p className="error">{notice}</p>}
  </main>;
}

createRoot(document.getElementById("root")!).render(<App />);
